import axios from 'axios';
import { CONFIG } from '../config';
import { MOCK_DATA } from './mocks';

// Instância real do Axios
const axiosInstance = axios.create({
  baseURL: CONFIG.API_BASE_URL,
  timeout: 15000,
  headers: {
    'Content-Type': 'application/x-www-form-urlencoded',
  },
});

/**
 * Utilitário para transformar objeto em Form Data (Padrão esperado pelo seu PHP)
 */
const toFormData = (data) => {
  const formData = new URLSearchParams();
  Object.keys(data).forEach(key => formData.append(key, data[key]));
  formData.append('secret', CONFIG.SECRET_KEY);
  return formData;
};

/**
 * Unified API Service
 */
const api = {
  // --- PASSENGER ENDPOINTS ---
  passenger: {
    login: async (cpf, senha) => {
      if (CONFIG.USE_MOCKS) return { data: MOCK_DATA.login };
      return axiosInstance.post('app/login_user.php', toFormData({ cpf, senha }));
    },
    register: async (dados) => {
      if (CONFIG.USE_MOCKS) return { data: { status: 'sucesso' } };
      return axiosInstance.post('app/cadastro.php', toFormData(dados));
    },
    getCategories: async (cidade_id) => {
      if (CONFIG.USE_MOCKS) return { data: MOCK_DATA.categorias };
      return axiosInstance.post('app/get_dados_cidade.php', toFormData({ cidade_id }));
    },
    requestRide: async (dados) => {
      if (CONFIG.USE_MOCKS) return { data: { status: 'sucesso', id_corrida: 999 } };
      return axiosInstance.post('app/insere_chamado.php', toFormData(dados));
    },
    getStatus: async (id_corrida) => {
      if (CONFIG.USE_MOCKS) return { data: MOCK_DATA.status_corrida };
      return axiosInstance.post('app/get_status_chamado.php', toFormData({ id_corrida }));
    }
  },

  // --- DRIVER ENDPOINTS ---
  driver: {
    login: async (cpf, senha) => {
      if (CONFIG.USE_MOCKS) return { data: MOCK_DATA.login }; // Reuse mock login
      return axiosInstance.post('motoristas/login.php', toFormData({ cpf, senha }));
    },
    updateLocation: async (id_motorista, status, lat, lng) => {
        if (CONFIG.USE_MOCKS) return { data: 'ok' };
        return axiosInstance.post('motoristas/atualiza_local.php', toFormData({ id_motorista, status, latitude: lat, longitude: lng }));
    },
    pollRides: async (id_motorista, cidade_id) => {
        if (CONFIG.USE_MOCKS) return { data: [] }; // Handle mock poll logic if needed
        return axiosInstance.post('motoristas/busca_corridas_disponiveis.php', toFormData({ id_motorista, cidade_id }));
    },
    acceptRide: async (id_motorista, id_corrida) => {
        if (CONFIG.USE_MOCKS) return { data: 'ok' };
        return axiosInstance.post('motoristas/aceitar.php', toFormData({ id_motorista, id_corrida }));
    }
  }
};

export default api;
